var maximumRequests = function(n, requests) {
    const m = requests.length;
    let ans = 0;
    function popcount(x) {
        let cnt = 0;
        while (x > 0) {
            cnt += x & 1;
            x >>= 1;
        }
        return cnt;
    }
    for (let mask = 0; mask < (1 << m); ++mask) {
        const count = popcount(mask);
        if (count <= ans) continue;
        const delta = Array(n).fill(0);
        for (let i = 0; i < m; ++i) {
            if (mask & (1 << i)) {
                delta[requests[i][0]]--;
                delta[requests[i][1]]++;
            }
        }
        let ok = true;
        for (let j = 0; j < n; ++j) {
            if (delta[j] !== 0) { ok = false; break; }
        }
        if (ok) ans = count;
    }
    return ans;
};
